update public.sarpras_katalog set spesifikasi='{"nama_form": "Perangkat Lunak Kasir (Software KDKMP)", "default": "Software Kasir: Alat kerja kasir untuk melakukan pemrosesan terhadap order, yang akan digunakan di KDKMP\nTerdiri dari: Software Point of Sales, ERP + WMS + KDKMP Solutions, HRIS Solutions", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/gry_software_kasir.jpg", "./assets/img/sarpras/gry_software_kasir_2.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='GRY_SOFTWARE_KASIR';
